using System.Collections.Generic;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "Corrupted Animal Data", menuName = "Data/Battle/Corrupted Animals/Corrupted Animal Data")]
public class CorruptedAnimalData : ScriptableObject
{
	[Header("Corrupted Animal Name")]
	public string CorruptedAnimalName;

	[Header("Animation")]
	public AnimationData AnimationData;

	[Header("Units Misc Data")]
	public bool EnableUnitsMiscData;

	[ShowIf("EnableUnitsMiscData")]
	public UnitsMiscData UnitsMiscData;

	[Header("SFX")]
	[SerializeField]
	public EnemySFXData EnemySFXData;

	[Header("Corruption")]
	[HorizontalLine(2f, EColor.Gray)]
	public List<RangedInt> StartingCorruptionList = new List<RangedInt>();

	public bool EventHealth;

	[Header("Over Corruption")]
	public List<int> MaxOverCorruptionList = new List<int>();

	public List<OverCorruptionAction> OverCorruptionActionList = new List<OverCorruptionAction>();

	[Header("Starting Effects")]
	public List<StartingEffectsList> StartingEffectsList = new List<StartingEffectsList>();

	[Header("Dice")]
	[HorizontalLine(2f, EColor.Gray)]
	public List<Dice> DiceList = new List<Dice>();

	[Header("Corruption Source")]
	[HorizontalLine(2f, EColor.Gray)]
	public bool CorruptionSource;

	public bool IgnoreCorruptionSourcePositioning;

	[ShowIf("CorruptionSource")]
	public int CorruptionSourceWithMinion;

	public bool Minion;

	public bool AlwaysSpawnInTheMiddle;

	[ShowIf("CorruptionSource")]
	public List<Minion> Minions = new List<Minion>();

	[HideInInspector]
	public bool MissingSomething;

	[Header("Joystick")]
	[HorizontalLine(2f, EColor.Gray)]
	[SerializeField]
	public UnitDetailJoystickInput unitDetailJoystickInput;

	public bool IgnoreAnomalyLevelStartingCorruptionModifier
	{
		get
		{
			if (StartingCorruptionList.Count > 1)
			{
				return !EventHealth;
			}
			return false;
		}
	}

	public string GetLocalizedName()
	{
		return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(CorruptedAnimalName + "_N");
	}

	public RangedInt GetStartingCorruption(int currentDifficultyLevelModifyEnemiesHighestIndex, int currentAreaIndex)
	{
		RangedInt rangedInt = default(RangedInt);
		if (EventHealth)
		{
			if (StartingCorruptionList.Count > currentAreaIndex)
			{
				return StartingCorruptionList[currentAreaIndex];
			}
			return StartingCorruptionList.Last();
		}
		if (StartingCorruptionList.Count > currentDifficultyLevelModifyEnemiesHighestIndex)
		{
			return StartingCorruptionList[currentDifficultyLevelModifyEnemiesHighestIndex];
		}
		return StartingCorruptionList.Last();
	}

	public int GetMaxOverCorruption(int currentDifficultyLevelModifyEnemiesHighestIndex)
	{
		int num = 0;
		if (MaxOverCorruptionList.Count > currentDifficultyLevelModifyEnemiesHighestIndex)
		{
			return MaxOverCorruptionList[currentDifficultyLevelModifyEnemiesHighestIndex];
		}
		return MaxOverCorruptionList.Last();
	}
}
